text.seasonTints:
/* ===== T136 真四季循環：夏／秋地面色與樹色調，置於 buildSprites 絕對尾端（接在 T128 detailPass 之後）。
   春（season()===0）沿用既有 SPR.grass/SPR.tree、冬沿用既有 SPR.grassW/SPR.treeW，兩者原有生成與亂數消耗序完全不動；
   本區塊純由既有已完工的 SPR.grass（4 變體）/SPR.tree（含 T104 擴充後 7 款）逐張以 tintCanvas 疊加半透明色調衍生
   SPR.grassS/grassA（長度 4）與 SPR.treeS/treeA（長度 7），陣列長度與日/冬版一致（冬季鐵律：季節切換陣列長度一致、不越界）；
   tintCanvas 用 source-atop 只在既有不透明像素上疊色，不影響剪影／輪廓，且不呼叫 rand()，故對其後（已無其後）任何生成序零位移 ===== */
{
  const tintCanvas=(src,w,h,col,a)=>{
    const[c,g]=cv(w,h);
    g.drawImage(src,0,0);
    g.globalCompositeOperation='source-atop';
    g.globalAlpha=a;g.fillStyle=col;g.fillRect(0,0,w,h);
    g.globalAlpha=1;g.globalCompositeOperation='source-over';
    return c;
  };
  SPR.grassS=SPR.grass.map(c=>tintCanvas(c,64,32,'#a8e070',.25));  // 夏：疊加嫩黃綠，草地更飽和茂盛
  SPR.grassA=SPR.grass.map(c=>tintCanvas(c,64,32,'#b8863a',.42));  // 秋：疊加土黃橙，草地轉枯黃
  SPR.treeS=SPR.tree.map(t=>({img:tintCanvas(t.img,40,48,'#a8e070',.18),ax:t.ax,ay:t.ay,w:t.w,h:t.h})); // 夏：樹冠偏濃綠
  SPR.treeA=SPR.tree.map(t=>({img:tintCanvas(t.img,40,48,'#c96a2c',.38),ax:t.ax,ay:t.ay,w:t.w,h:t.h})); // 秋：樹冠偏暖橙

text.treeSnow:
SPR.treeW=[];
for(let v=0;v<4;v++){
  const[c,g]=cv(40,48),[s,sg]=cv(40,48);
  dia(g,20,36,10,'rgba(90,110,140,.20)');             // 落影（雪地偏冷）
  if(v===2){                                          // 松樹：每層頂 2 行雪白
    sg.fillStyle='#6b4a2f';sg.fillRect(19,34,3,8);
    sg.fillStyle='#57402a';sg.fillRect(21,34,1,8);
    const tc=['#2f6b3f','#3a7d4b'];
