    }
    sg.fillStyle='#eef4f8';sg.fillRect(18,4,5,3);sg.fillStyle='#2f6b3f';sg.fillRect(18,7,5,2);
  }else if(v===3){                                    // 灌木叢：頂部積雪
    sg.fillStyle='#3d7a3c';sg.fillRect(8,26,14,10);sg.fillRect(20,29,12,8);
    sg.fillStyle='#4b8f45';sg.fillRect(9,24,11,7);sg.fillRect(21,27,9,6);
    sg.fillStyle='#63ad55';sg.fillRect(11,25,6,4);sg.fillRect(23,28,5,3);
    sg.fillStyle='#eef4f8';sg.fillRect(9,24,11,2);sg.fillRect(21,27,9,2);
    sg.fillStyle='#ffffff';sg.fillRect(9,24,11,1);sg.fillRect(21,27,9,1);
    sg.fillStyle='#2e5f2f';sg.fillRect(8,34,24,2);
  }else{                                              // 闊葉樹：樹冠頂 40% 雪簷
    const base=v?'#38713a':'#3d7a3c', mid=v?'#468747':'#4b8f45';
    sg.fillStyle='#6b4a2f';sg.fillRect(18,30,4,11);
    sg.fillStyle='#57402a';sg.fillRect(20,30,2,11);
    sg.fillStyle=base;sg.fillRect(10,8,20,16);sg.fillRect(8,12,24,10);
    sg.fillStyle=mid;sg.fillRect(12,6,16,8);sg.fillRect(13,7,14,13);
    sg.fillStyle='#63ad55';sg.fillRect(14,7,10,7);
    sg.fillStyle='#eef4f8';sg.fillRect(10,8,20,5);sg.fillRect(12,6,16,3);sg.fillRect(8,12,24,2);
    sg.fillStyle='#ffffff';sg.fillRect(10,13,20,1);sg.fillRect(8,14,24,1);
    sg.fillStyle='#2e5f2f';sg.fillRect(10,22,20,2);sg.fillRect(12,24,16,1);
  }
  outlineSprite(s,24,40,28);
  g.drawImage(s,0,0);
  SPR.treeW.push({img:c,ax:20,ay:45,w:40,h:48});
}

