text.updRain:
function updRain(dt){
  if(!weather){if(rain.length)rain.length=0;return;}
  const win=inWinter();                       // 冬季：雪花直落＋隨 visT 微擺；非冬季：斜雨（T18）
  const cap=Math.floor((weather===2?240:120)*(quality===0?.5:quality===2?1.4:1)); // T97：雨/雪粒子上限依效能檔縮放
  const f=dt*60;                              // 以 60fps 為基準的幀係數（後備迴圈 dt 大時等比加速）
  const vy=(win?6:14)*cam.z*f;
  while(rain.length<cap)rain.push({x:Math.random()*(W+240)-40,y:Math.random()*H});
  if(rain.length>cap)rain.length=cap;         // 暴雨轉小雨→截斷
  for(const p of rain){
    const ww443=screenWorld443(p.x,p.y),lw443=inMap(ww443[0],ww443[1])?localWind443(ww443[0],ww443[1]):windX441;
    const vx443=((win?Math.sin(visT*.8)*1.4:-1.2)+lw443*(win?2.2:4.2))*cam.z*f; /* T443：雨雪按所在城市格讀局部風；地圖外仍吃 T441 全局風 */
    p.x+=vx443;p.y+=vy;
    if(p.y>H||p.x<-40||p.x>W+200){p.x=Math.random()*(W+240)-40;p.y=-Math.random()*40;} // T443：強順風可向右出界，同樣回收
  }
}

text.drawRain:
function drawRain(z){
  if(inWinter()){                             // 冬季雪花：2×2 白點（T18）
    const s=Math.max(2,Math.round(2*z));
    ctx.fillStyle='rgba(255,255,255,.85)';
    for(const p of rain)ctx.fillRect(p.x,p.y,s,s);
    return;
  }
  const w=z,L=Math.max(2,Math.round(2*z));
  ctx.fillStyle='rgba(200,220,255,.5)';
  for(const p of rain){                       // 2 段偏轉 fillRect＝斜向雨絲（配合 vx<0,vy>0）
    ctx.fillRect(p.x,p.y,w,L);
    ctx.fillRect(p.x-w,p.y+L,w,L);
  }
}

