text.rainbowDraw:
if(rainbowT>0){ // T248 雨後彩虹（Opus 親手，天氣多樣化）——雨/暴雨轉晴且非冬時，天空出現七色彩虹弧，隨 rainbowT 淡出；圓心置螢幕下方＝弧橫跨上方天空(下緣被地形覆蓋＝從地平線起拱)，'lighter' 疊加於淺藍天；純渲染計時 dt 遞減(不進存檔、newWorld/load 重置)、weather!==0(再下雨)/遠景不繪、__noRainbow 開關
  if(weather===0&&cam.z>=.5&&!window.__noRainbow){
    const ra=clamp(rainbowT/9,0,1)*.46, RB=['#e0504a','#e8934a','#e8d24a','#54b858','#4a90d8','#5a5ac8','#9a54c8'];
    const rcx=W*.5, rcy=H*1.08, rout=H*.92, lw=Math.max(2,H*.011);
    ctx.save();ctx.globalAlpha=ra;ctx.lineWidth=lw; // source-over：半透明色帶顯真色（'lighter' 會把暖帶疊在藍天上洗白，同 T195/T207 飽和教訓）
    for(let i=0;i<7;i++){ctx.strokeStyle=RB[i];ctx.beginPath();ctx.arc(rcx,rcy,Math.max(1,rout-i*lw),Math.PI*1.16,Math.PI*1.84);ctx.stroke();}
    ctx.restore();
  }
  rainbowT=Math.max(0,rainbowT-dt);

text.flashDraw:
if(flashT>0){
  const flashA=Math.min(.85,flashT*2);
  ctx.fillStyle=`rgba(255,255,255,${flashA.toFixed(3)})`;
  ctx.fillRect(0,0,W,H);
  if(fxOn&&wxUp){ // T154：沿用 T149 光影層 'lighter' 疊加手法，閃電瞬間額外疊一層暖白全域補光（一幀高亮，隨 flashT 同步衰減）；fxOn／wxUp 任一為假（z<0.5／quality===0／__noLight／__noWx）時維持改動前純白閃光，退回既有簡單版本
    ctx.save();
    ctx.globalCompositeOperation='lighter';
    ctx.fillStyle=`rgba(255,250,225,${(flashA*.45).toFixed(3)})`;
    ctx.fillRect(0,0,W,H);
    ctx.restore();
  }
  if(flashT>.15&&!lodMini&&!window.__noBolt){ // T195 分岔閃電線形（Opus 親手，審計缺口）——原僅全屏白閃無電光形狀。flashT 高時畫螢幕空間鋸齒主幹+1 分岔電光，路徑由 streetHash(day) 決定性(同日同一形狀、隨 flashT 淡出)；'lighter' 藍白疊加+粗淡光暈；純幾何不消耗 R()、不改模擬。__noBolt 開關、遠景不繪
    const sd=day, boltA=Math.min(1,(flashT-.15)*3.2);
    let cx2=(.24+streetHash(sd,1,880)*.52)*W, cy2=0; const pts=[[cx2,cy2]];
    for(let s=1;s<=7;s++){cx2+=(streetHash(sd,s,881)-.5)*W*.14;cy2=(s/7)*H*.74;pts.push([cx2,cy2]);}
    const bi=3+Math.floor(streetHash(sd,0,882)*2); let fx=pts[bi][0],fy=pts[bi][1]; const fpts=[[fx,fy]];
    for(let s=1;s<=3;s++){fx+=(streetHash(sd,s,883)-.32)*W*.11;fy+=H*.11;fpts.push([fx,fy]);}
    const stroke=(ps,lw,col)=>{ctx.strokeStyle=col;ctx.lineWidth=lw;ctx.beginPath();ctx.moveTo(ps[0][0],ps[0][1]);for(let k=1;k<ps.length;k++)ctx.lineTo(ps[k][0],ps[k][1]);ctx.stroke();};
    ctx.save();ctx.lineCap='round';ctx.lineJoin='round'; // source-over：白閃已飽和至 255，電光以實色藍白覆蓋才可見（藍白色亦符合真實閃電通道）
    stroke(pts,Math.max(5,8*z),`rgba(120,165,240,${(boltA*.5).toFixed(3)})`);  // 主幹光暈（偏藍）
    stroke(fpts,Math.max(3,5*z),`rgba(120,165,240,${(boltA*.42).toFixed(3)})`); // 分岔光暈
    stroke(pts,Math.max(1.6,2.4*z),`rgba(170,205,255,${boltA.toFixed(3)})`);    // 主幹芯（藍白）
    stroke(fpts,Math.max(1.2,1.8*z),`rgba(170,205,255,${(boltA*.9).toFixed(3)})`); // 分岔芯
    ctx.restore();
  }
  flashT=Math.max(0,flashT-dt);
